// Calculate customer loyalty metrics and determine retention strategy
const customerData = $input.first().json;
const loyaltyData = $input.all();

// Find customer in loyalty data
const customerEmail = customerData['Customer Email'];
const customerLoyalty = loyaltyData.find(row => row.json['Customer Email'] === customerEmail) || {};

// Calculate visit frequency and value
const visitCount = parseInt(customerLoyalty['Total Visits'] || '1');
const totalSpent = parseFloat(customerLoyalty['Total Spent'] || customerData['Invoice Amount'] || '0');
const lastVisitDate = new Date(customerData['Date']);
const daysSinceLastVisit = Math.floor((new Date() - lastVisitDate) / (1000 * 60 * 60 * 24));

// Determine customer tier
let customerTier = 'New';
if (visitCount >= 10 || totalSpent >= 1000) {
  customerTier = 'VIP';
} else if (visitCount >= 5 || totalSpent >= 500) {
  customerTier = 'Loyal';
} else if (visitCount >= 3) {
  customerTier = 'Regular';
}

// Determine retention strategy
let retentionStrategy = 'standard';
let offerType = 'thank_you';
let discountPercent = 0;
let reminderDays = 90;

if (customerTier === 'VIP') {
  retentionStrategy = 'vip_exclusive';
  offerType = 'exclusive_discount';
  discountPercent = 20;
  reminderDays = 60;
} else if (customerTier === 'Loyal') {
  retentionStrategy = 'loyalty_reward';
  offerType = 'loyalty_discount';
  discountPercent = 15;
  reminderDays = 75;
} else if (customerTier === 'Regular') {
  retentionStrategy = 'engagement_boost';
  offerType = 'return_discount';
  discountPercent = 10;
  reminderDays = 90;
} else {
  retentionStrategy = 'new_customer_nurture';
  offerType = 'welcome_offer';
  discountPercent = 5;
  reminderDays = 120;
}

// Calculate next contact date
const nextContactDate = new Date();
nextContactDate.setDate(nextContactDate.getDate() + reminderDays);

return {
  ...customerData,
  customerTier,
  visitCount,
  totalSpent,
  daysSinceLastVisit,
  retentionStrategy,
  offerType,
  discountPercent,
  reminderDays,
  nextContactDate: nextContactDate.toISOString().split('T')[0],
  retentionScore: Math.min(100, (visitCount * 10) + (totalSpent / 10)),
  churnRisk: daysSinceLastVisit > 180 ? 'High' : daysSinceLastVisit > 90 ? 'Medium' : 'Low'
};

